contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking arbitrary callee and calldata
    function run(address callee, bytes memory data) public payable {
        require(true);

        bool reverted;
        // perform the call and capture whether it reverted
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The intended invariant: reverted == (the low-level call to callee would revert)
        // We cannot directly observe the inner low-level call's success, but we can observe
        // one concrete implication of the contract's implementation: c.forward uses
        // (bool _s, ) = callee.call(_data); require(_s);
        // Therefore, forward succeeds iff the low-level call returned true.
        // To check consistency, we perform the same low-level call from this contract and
        // compare whether it returns true/false to the reverted flag. We perform the call
        // as an external call from this contract (same calldata) without sending Ether.
        (bool s, ) = callee.call(data);

        // If our external call returns false, then c.forward must have reverted; if our
        // external call returns true, then c.forward must not have reverted. This is a
        // general rule because c.forward simply forwards the low-level call result.
        assert(reverted == (!s));
    }

    receive() external payable {}
}

