contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take a callee and arbitrary calldata. We also take an amount to send from this test
    // contract into C before invoking forward, to create some initial balance in C that could be moved.
    function run(address callee, bytes calldata data, uint256 fund) public payable {
        require(address(this).balance >= fund);
        // Fund C by sending Ether to it from this contract if fund > 0
        if (fund > 0) {
            (bool ok,) = address(c).call{value: fund}(""");
            require(ok);
        }

        uint256 beforeC = address(c).balance;
        uint256 beforeCallee = callee.balance;

        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterCallee = callee.balance;

        // General rule: if forward returned (did not revert) then C's balance did not increase,
        // and if the callee is an EOA (no code) then the callee's balance did not increase either.
        // We express "callee is an EOA" by checking callee.code.length == 0.
        assert(reverted || (afterC <= beforeC && (callee.code.length != 0 || afterCallee <= beforeCallee)));
    }

    receive() external payable { }
}

