contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: callee address, arbitrary calldata, and amount to fund C before calling forward
    function run(address callee, bytes calldata data, uint256 fund) public payable {
        require(address(this).balance >= fund);
        // Fund C if requested. This is a top-level call not nested.
        if (fund > 0) {
            (bool ok,) = address(c).call{value: fund}("\x00");
            require(ok);
        }

        uint256 beforeC = address(c).balance;
        uint256 beforeCallee = callee.balance;

        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterCallee = callee.balance;

        // Assert general rule: if forward did not revert then C's balance did not increase,
        // and if callee is an EOA (no code) then callee's balance did not increase.
        assert(reverted || (afterC <= beforeC && (callee.code.length != 0 || afterCcallee_nonincr(beforeC, beforeCallee, afterC, afterCallee))));
    }

    // helper implemented as internal pure to avoid using callee.code.length inside complex expr
    // It returns true iff callee's balance did not increase (afterCallee <= beforeCallee).
    // Note: internal functions are allowed; they don't make calls on c.
    function afterCcallee_nonincr(uint256 /*beforeC*/, uint256 beforeCallee, uint256 /*afterC*/, uint256 afterCallee) internal pure returns (bool) {
        return afterCallee <= beforeCallee;
    }

    receive() external payable { }
}

