    function run(address callee, bytes calldata data) public payable {
        require(true);

        // Record c's balance before
        uint256 before = address(c).balance;

        // Perform the call through c, catching whether it reverted
        bool reverted;
        try c.forward(callee, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record c's balance after
        uint256 after = address(c).balance;

        // If c's balance increased (meaning the callee sent Ether into c during the forwarded call),
        // then the forward call must have succeeded (i.e., not reverted). This captures the rule that
        // incoming value to c during the inner call cannot be observed if the outer call reverted.
        assert(!(after > before) || (!reverted));
    }

    receive() external payable {}
